-- GenDB engine variant Q10-commuted_comparisons: template q10.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  c_custkey,
  c_name,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue,
  c_acctbal,
  n_name,
  c_address,
  c_phone,
  c_comment
FROM customer, orders, lineitem, nation
WHERE
  o_custkey = c_custkey
  AND o_orderkey = l_orderkey
  AND $1 <= o_orderdate
  AND $1 + INTERVAL '3 MONTH' > o_orderdate
  AND 'R' = l_returnflag
  AND n_nationkey = c_nationkey
GROUP BY
  c_custkey,
  c_name,
  c_acctbal,
  c_phone,
  n_name,
  c_address,
  c_comment
ORDER BY
  revenue DESC
LIMIT 20
